customCSS:
.t, .history { color: #6b7089; }
.join { color: #b4be82; }
.part, .quit { color: #6b7089; }
.kick, .error { color: #e27878; }
.notice { color: #e2a478; }
.action { color: #a093c7; }
.mode, .nick, .topic, .server { color: #89b8c2; }
.highlight { color: #c6c8d1; background-color: #272c42; border-left: 3px solid #a093c7; padding-left: 8px; }
.reply { color: #6b7089; border-left: 2px solid #84a0c6; padding-left: 6px; }
.oper { color: #161821; background-color: #e2a478; }
.reactions { color: #84a0c6; background-color: #1e2132; }
.card { background-color: #1e2132; border-color: #6b7089; }
.card-title { color: #84a0c6; }
.card-desc { color: #6b7089; }
.daychange { color: #6b7089; border-color: #1e2132; }
